                ))}
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <div className="h-[220px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                layout="vertical"
                data={ladderData}
                margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
