                <Legend />
                <Bar
                  dataKey="rolAvgYoy"
                  name="Avg RoL YoY %"
                  fill={CYAN}
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  dataKey="residualBasketAvgYoy"
                  name="Avg residual basket YoY %"
                  fill={VIOLET}
                  radius={[4, 4, 0, 0]}
                />
